import{_ as o,o as a,c as r,a4 as t}from"./chunks/framework.B6zrJok8.js";const p=JSON.parse('{"title":"Versioning & Release","description":"","frontmatter":{"title":"Versioning & Release"},"headers":[],"relativePath":"operations/versioning.md","filePath":"operations/versioning.md","lastUpdated":null}'),n={name:"operations/versioning.md"};function s(i,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="versioning-release" tabindex="-1">Versioning &amp; Release <a class="header-anchor" href="#versioning-release" aria-label="Permalink to &quot;Versioning &amp; Release&quot;">​</a></h1><p>How we version the CLI and what counts as a breaking change.</p><hr><h2 id="versioning-strategy-semver" tabindex="-1">Versioning strategy (SemVer) <a class="header-anchor" href="#versioning-strategy-semver" aria-label="Permalink to &quot;Versioning strategy (SemVer)&quot;">​</a></h2><p>We use <strong>Semantic Versioning</strong> (MAJOR.MINOR.PATCH) in <code>package.json</code>:</p><table tabindex="0"><thead><tr><th>Bump</th><th>When</th></tr></thead><tbody><tr><td><strong>PATCH</strong></td><td>Bug fixes, doc-only changes, internal refactors with no behavior or API change.</td></tr><tr><td><strong>MINOR</strong></td><td>New commands, new flags, new make variables, new optional config or env vars. Deprecations (old behavior still works for at least one release).</td></tr><tr><td><strong>MAJOR</strong></td><td>Removing or changing behavior of existing commands or flags, changing exit codes, or breaking config file format or required environment variables.</td></tr></tbody></table><hr><h2 id="deprecation-policy" tabindex="-1">Deprecation policy <a class="header-anchor" href="#deprecation-policy" aria-label="Permalink to &quot;Deprecation policy&quot;">​</a></h2><ul><li><strong>Announce first:</strong> When we want to remove or change a command/flag/behavior, we document it as deprecated (in release notes and, if possible, in CLI help or a warning).</li><li><strong>Support window:</strong> Deprecated behavior remains supported for at least one <strong>minor</strong> release before removal or breaking change in a <strong>major</strong> release.</li><li><strong>Docs:</strong> Deprecations and replacements are listed in release notes and in the <a href="/reference/commands.html">Commands Reference</a> or relevant config docs.</li></ul><hr><h2 id="release-checklist" tabindex="-1">Release checklist <a class="header-anchor" href="#release-checklist" aria-label="Permalink to &quot;Release checklist&quot;">​</a></h2><p>Before tagging a release or handing off to producers:</p><ol><li><strong>Smoke test:</strong> <code>make help</code>, then <code>make setup</code> (or ensure config exists), <code>make pull</code>, <code>make build</code>, <code>make preview</code> for at least one date.</li><li><strong>Quality:</strong> <code>make check</code> (lint + tests).</li><li><strong>Docs:</strong> <code>make docs-build</code> so VitePress builds and links are valid.</li><li><strong>OCAPI (if used):</strong> Set env vars from <code>.env.example</code>, run <code>make health</code>; optionally run <code>make push</code> with <code>YES=1</code> on a test date.</li><li><strong>Version and changelog:</strong> Update <code>version</code> in <code>package.json</code> and note changes (in CHANGELOG or release notes).</li></ol><p>See <a href="/operations/runbook.html#release-launch-checklist">Runbook — Release / Launch Checklist</a> for the same list in context.</p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/operations/runbook.html">Runbook</a> — Daily ops and release steps</li><li><a href="/operations/github-workflow.html">GitHub Workflow</a> — CI and deployment</li></ul>',17)])])}const m=o(n,[["render",s]]);export{p as __pageData,m as default};
